-- 29 comment rules from templates/comment_rules.software.json for tenant dalatech
begin;
update comment_rules set enabled = false
 where tenant_id = (select id from tenants where slug = $r$dalatech$r$)
   and rule_key not in ($r$complaint$r$, $r$complaint_phrases$r$, $r$complaint_phrases_lat$r$, $r$complaint_call_mn$r$, $r$complaint_call_lat$r$, $r$complaint_days_mn$r$, $r$complaint_days_lat$r$, $r$complaint_money_mn$r$, $r$complaint_money_lat$r$, $r$complaint_human_mn$r$, $r$complaint_human_lat$r$, $r$complaint_words$r$, $r$complaint_bad$r$, $r$ad_keyword$r$, $r$price$r$, $r$price_stems$r$, $r$location$r$, $r$booking$r$, $r$info$r$, $r$info_stems$r$, $r$product_question_q_word$r$, $r$product_question_q_stem$r$, $r$product_question_end_word$r$, $r$product_question_end_stem$r$, $r$any_question_mark$r$, $r$praise$r$, $r$praise_stems$r$, $r$laughter$r$, $r$greeting$r$);
insert into comment_rules (tenant_id, rule_key, verdict, matcher, enabled, provenance)
select t.id, v.rule_key, v.verdict, v.matcher, true, 'seeded'
  from tenants t, (values
  ($r$complaint$r$, $r$escalate$r$, $r${"mode":"contains_stem","stems":["гомдол","gomdol","луйвар","luivar","залилан","zalilan","залилсан","zalilsan","сүйтгэ","suitge","svitge","сүйрүүл","suiruul","шатаа","shataa","шатсан","shatsan","шатчих","shatchih","муудсан","muudsan","муудуул","muuduul","ичгүүргүй","ichguurgui","ichgvvrgvi","бүдүүлэг","buduuleg","bvdvvleg","хариулахгүй","hariulahgui","hariulahgvi","хүлээлгэ","huleelge","hvleelge","хүлээсээр","huleeseer","дундуур","dunduur","худлаа","hudlaa","муухай","muuhai","тэнэг","teneg","хогийн","hogiin"]}$r$::jsonb),
  ($r$complaint_phrases$r$, $r$escalate$r$, $r${"mode":"stem_sequence","stems":["утсаа","ав"],"windowCp":20}$r$::jsonb),
  ($r$complaint_phrases_lat$r$, $r$escalate$r$, $r${"mode":"stem_sequence","stems":["utsaa","av"],"windowCp":20}$r$::jsonb),
  ($r$complaint_call_mn$r$, $r$escalate$r$, $r${"mode":"stem_sequence","stems":["залга","авахгүй"],"windowCp":30}$r$::jsonb),
  ($r$complaint_call_lat$r$, $r$escalate$r$, $r${"mode":"stem_sequence","stems":["zalga","avahgui"],"windowCp":30}$r$::jsonb),
  ($r$complaint_days_mn$r$, $r$escalate$r$, $r${"mode":"stem_sequence","stems":["өдөр","залга"],"windowCp":20}$r$::jsonb),
  ($r$complaint_days_lat$r$, $r$escalate$r$, $r${"mode":"stem_sequence","stems":["udur","zalga"],"windowCp":20}$r$::jsonb),
  ($r$complaint_money_mn$r$, $r$escalate$r$, $r${"mode":"stem_sequence","stems":["мөнгө","буцаа"],"windowCp":20}$r$::jsonb),
  ($r$complaint_money_lat$r$, $r$escalate$r$, $r${"mode":"stem_sequence","stems":["mungu","butsaa"],"windowCp":20}$r$::jsonb),
  ($r$complaint_human_mn$r$, $r$escalate$r$, $r${"mode":"stem_sequence","stems":["хүнтэй","холбог"],"windowCp":20}$r$::jsonb),
  ($r$complaint_human_lat$r$, $r$escalate$r$, $r${"mode":"stem_sequence","stems":["huntei","holbog"],"windowCp":20}$r$::jsonb),
  ($r$complaint_words$r$, $r$escalate$r$, $r${"mode":"has_word","words":["ai bish","ай биш","бот биш","bot bish","хог"]}$r$::jsonb),
  ($r$complaint_bad$r$, $r$escalate$r$, $r${"mode":"all_of","matchers":[{"mode":"has_word","words":["муу","muu"]},{"mode":"not","matcher":{"mode":"has_word","words":["биш","bish","bishee","бишээ"]}}]}$r$::jsonb),
  ($r$ad_keyword$r$, $r$reply$r$, $r${"mode":"has_word","words":["message","мессеж","messege","combo","комбо"]}$r$::jsonb),
