  ($r$price_stems$r$, $r$reply$r$, $r${"mode":"all_of","matchers":[{"mode":"contains_stem","stems":["үнийн","uniin","vniin","үнэтэй","unetei","vnetei","хэдээр","hedeer","төлбөр","tulbur","tolbor","хямдрал","hymdral","hyamdral","урамшуулал","uramshuulal","төгрөг","tugrug"]},{"mode":"not","matcher":{"mode":"has_word","words":["хаха","хахаха","хэхэ","хихи","haha","hahaha","hehe","hihi","xaxa","lol","kkk","😂","🤣","😆","😅","😹"]}},{"mode":"not","matcher":{"mode":"contains_stem","stems":["хаха","хэхэ","haha","hehe","xaxa"]}}]}$r$::jsonb),
  ($r$location$r$, $r$reply$r$, $r${"mode":"contains_stem","stems":["хаяг","hayg","hayag","xayg","haig","байршил","bairshil","хаана","haana","xaana","хаашаа","haashaa","салбарууд","salbaruud"]}$r$::jsonb),
  ($r$booking$r$, $r$reply$r$, $r${"mode":"all_of","matchers":[{"mode":"contains_stem","stems":["захиал","zahial","zakhial","бүртгүүл","burtguul"]},{"mode":"not","matcher":{"mode":"has_word","words":["хаха","хахаха","хэхэ","хихи","haha","hahaha","hehe","hihi","xaxa","lol","kkk","😂","🤣","😆","😅","😹"]}},{"mode":"not","matcher":{"mode":"contains_stem","stems":["хаха","хэхэ","haha","hehe","xaxa"]}}]}$r$::jsonb),
  ($r$info$r$, $r$reply$r$, $r${"mode":"all_of","matchers":[{"mode":"has_word","words":["ib","pm","dm","info","инфо","иб","пм","inbox","инбокс","дэлгэрэнгүй","delgerengui","delgerengvi","мэдээлэл","medeelel","detail","details","dtl","утас","utas","утсаа","utsaa","дугаар","dugaar","дугаараа","dugaaraa"]},{"mode":"not","matcher":{"mode":"has_word","words":["хаха","хахаха","хэхэ","хихи","haha","hahaha","hehe","hihi","xaxa","lol","kkk","😂","🤣","😆","😅","😹"]}},{"mode":"not","matcher":{"mode":"contains_stem","stems":["хаха","хэхэ","haha","hehe","xaxa"]}}]}$r$::jsonb),
  ($r$info_stems$r$, $r$reply$r$, $r${"mode":"all_of","matchers":[{"mode":"contains_stem","stems":["дэлгэрэнгүй","delgerengu","delgerengv","мэдээлэл","medeelel","medeell","инбокс","inbox","холбогд","holbogd","утасны","utasnii","дугаар","dugaar","ibee","ibeer","ибээр","pmeer","пмээр"]},{"mode":"not","matcher":{"mode":"has_word","words":["хаха","хахаха","хэхэ","хихи","haha","hahaha","hehe","hihi","xaxa","lol","kkk","😂","🤣","😆","😅","😹"]}},{"mode":"not","matcher":{"mode":"contains_stem","stems":["хаха","хэхэ","haha","hehe","xaxa"]}}]}$r$::jsonb),
