  ($r$product_question_q_stem$r$, $r$reply$r$, $r${"mode":"all_of","matchers":[{"mode":"has_word","words":["?","уу","үү","юу","юү","вэ","бэ","бол","uu","vv","yu","yuu","ve","we","be","bol"]},{"mode":"contains_stem","stems":["вэбсайт","website","вебсайт","websait","чатбот","chatbot","автомат","avtomat","программ","програм","program","мессенжер","messenger","инстаграм","instagram","ажилтн","ajiltn","туслах","tuslah"]},{"mode":"not","matcher":{"mode":"has_word","words":["гоё","гоёо","гоёоо","goy","goyo","goyoo","хөөрхөн","hoorhon","huurhun","hvvrhun","сайхан","saihan","гайхалтай","gaihaltai","мундаг","mundag","амжилт","amjilt","баярлалаа","bayarlalaa","bayrlalaa","wow","woow","вау","super","супер","nice"]}},{"mode":"not","matcher":{"mode":"contains_stem","stems":["гоёмсог","хөөрхөн","гайхалт","мундаг","mundag","амжилт","amjilt","баярлал","bayarlal","bayrlal","чадварлаг","chadvarlag"]}},{"mode":"not","matcher":{"mode":"has_word","words":["хаха","хахаха","хэхэ","хихи","haha","hahaha","hehe","hihi","xaxa","lol","kkk","😂","🤣","😆","😅","😹"]}},{"mode":"not","matcher":{"mode":"contains_stem","stems":["хаха","хэхэ","haha","hehe","xaxa"]}}]}$r$::jsonb),
  ($r$product_question_end_word$r$, $r$reply$r$, $r${"mode":"all_of","matchers":[{"mode":"ends_with","endings":["уу","үү","юу","юү","вэ","бэ","uu","vv","yu","ve","we","be"]},{"mode":"has_word","words":["дали","dali","вира","vira","эхо","echo","eho","нова","nova","ора","ora","ai","аи","бот","bot","сайт","site","вэб","web","чатбот","chatbot","туслах","tuslah","ажилтан","ajiltan","програм","программ","program","систем","system","автомат","avtomat"]},{"mode":"not","matcher":{"mode":"has_word","words":["гоё","гоёо","гоёоо","goy","goyo","goyoo","хөөрхөн","hoorhon","huurhun","hvvrhun","сайхан","saihan","гайхалтай","gaihaltai","мундаг","mundag","амжилт","amjilt","баярлалаа","bayarlalaa","bayrlalaa","wow","woow","вау","super","супер","nice"]}},{"mode":"not","matcher":{"mode":"contains_stem","stems":["гоёмсог","хөөрхөн","гайхалт","мундаг","mundag","амжилт","amjilt","баярлал","bayarlal","bayrlal","чадварлаг","chadvarlag"]}},{"mode":"not","matcher":{"mode":"has_word","words":["хаха","хахаха","хэхэ","хихи","haha","hahaha","hehe","hihi","xaxa","lol","kkk","😂","🤣","😆","😅","😹"]}},{"mode":"not","matcher":{"mode":"contains_stem","stems":["хаха","хэхэ","haha","hehe","xaxa"]}}]}$r$::jsonb),
  ($r$product_question_end_stem$r$, $r$reply$r$, $r${"mode":"all_of","matchers":[{"mode":"ends_with","endings":["уу","үү","юу","юү","вэ","бэ","uu","vv","yu","ve","we","be"]},{"mode":"contains_stem","stems":["вэбсайт","website","вебсайт","websait","чатбот","chatbot","автомат","avtomat","программ","програм","program","мессенжер","messenger","инстаграм","instagram","ажилтн","ajiltn","туслах","tuslah"]},{"mode":"not","matcher":{"mode":"has_word","words":["гоё","гоёо","гоёоо","goy","goyo","goyoo","хөөрхөн","hoorhon","huurhun","hvvrhun","сайхан","saihan","гайхалтай","gaihaltai","мундаг","mundag","амжилт","amjilt","баярлалаа","bayarlalaa","bayrlalaa","wow","woow","вау","super","супер","nice"]}},{"mode":"not","matcher":{"mode":"contains_stem","stems":["гоёмсог","хөөрхөн","гайхалт","мундаг","mundag","амжилт","amjilt","баярлал","bayarlal","bayrlal","чадварлаг","chadvarlag"]}},{"mode":"not","matcher":{"mode":"has_word","words":["хаха","хахаха","хэхэ","хихи","haha","hahaha","hehe","hihi","xaxa","lol","kkk","😂","🤣","😆","😅","😹"]}},{"mode":"not","matcher":{"mode":"contains_stem","stems":["хаха","хэхэ","haha","hehe","xaxa"]}}]}$r$::jsonb),
  ($r$any_question_mark$r$, $r$reply$r$, $r${"mode":"all_of","matchers":[{"mode":"has_word","words":["?"]},{"mode":"not","matcher":{"mode":"whole_message","phrases":["сайн байна уу","сайн уу","sain baina uu","sain bnuu","sn bnu","hi","hello","сайн байцгаана уу"]}},{"mode":"not","matcher":{"mode":"has_word","words":["гоё","гоёо","гоёоо","goy","goyo","goyoo","хөөрхөн","hoorhon","huurhun","hvvrhun","сайхан","saihan","гайхалтай","gaihaltai","мундаг","mundag","амжилт","amjilt","баярлалаа","bayarlalaa","bayrlalaa","wow","woow","вау","super","супер","nice"]}},{"mode":"not","matcher":{"mode":"contains_stem","stems":["гоёмсог","хөөрхөн","гайхалт","мундаг","mundag","амжилт","amjilt","баярлал","bayarlal","bayrlal","чадварлаг","chadvarlag"]}},{"mode":"not","matcher":{"mode":"has_word","words":["хаха","хахаха","хэхэ","хихи","haha","hahaha","hehe","hihi","xaxa","lol","kkk","😂","🤣","😆","😅","😹"]}},{"mode":"not","matcher":{"mode":"contains_stem","stems":["хаха","хэхэ","haha","hehe","xaxa"]}}]}$r$::jsonb),
